// ── Mensagens da cadência de follow-up (30 dias) ─────────────────
//
//  Cada mensagem é personalizada por etapa e orientada à saúde preventiva.
//  O marcador [FOLLOWUP-N] é salvo no banco para rastrear a cadência.
//
const CADENCIA = [

  // ── FU-1: Lembrete acolhedor (dia 1) ─────────────────────────────
  {
    tag: '[FOLLOWUP-1]',
    texto: (nome) =>
      `Olá, ${nome}! 😊\n\n` +
      `Passamos para lembrar do orçamento que preparamos para você aqui na *Total Quality*.\n\n` +
      `Cuidar da saúde com exames preventivos é um dos maiores presentes que você pode dar a si mesmo(a) — e nós estamos prontos para facilitar isso! ❤️\n\n` +
      `Posso reservar um horário especial para você esta semana?\n\n` +
      `_Total Quality — (12) 3887-3535_`
  },

  // ── FU-2: Importância da saúde preventiva (dia 3) ─────────────────
  {
    tag: '[FOLLOWUP-2]',
    texto: (nome) =>
      `${nome}, você sabia que *mais de 80% das doenças crônicas* são detectáveis precocemente com exames de rotina? 🩺\n\n` +
      `Hemograma, glicemia, colesterol, hormônios, ultrassom — esses exames são aliados poderosos da sua saúde preventiva.\n\n` +
      `Na *Total Quality* você tem:\n` +
      `✅ Laudos rápidos e assinados por especialistas\n` +
      `✅ Mais de 23 anos cuidando da saúde do Litoral Norte\n` +
      `✅ Atendimento humanizado do início ao fim\n\n` +
      `Que tal dar esse passo hoje? Posso verificar os melhores horários para você! 😊\n\n` +
      `_Total Quality — (12) 3887-3535_`
  },

  // ── FU-3: Urgência leve — agenda (dia 7) ─────────────────────────
  {
    tag: '[FOLLOWUP-3]',
    texto: (nome) =>
      `Olá, ${nome}! 👋\n\n` +
      `Nossa agenda está *bem disputada* nessa época do ano — especialmente para ultrassons, tomografias e exames de coluna.\n\n` +
      `Temos *alguns horários disponíveis* ainda esta semana. Seria uma pena você esperar mais do que o necessário para cuidar da sua saúde. 💛\n\n` +
      `Posso garantir sua vaga agora? É rápido — preciso apenas do seu nome e data preferida! 📅\n\n` +
      `_Total Quality — (12) 3887-3535_`
  },

  // ── FU-4: Check-in e ajuda personalizada (dia 14) ─────────────────
  {
    tag: '[FOLLOWUP-4]',
    texto: (nome) =>
      `${nome}, tudo bem? 😊\n\n` +
      `Estamos passando para saber se ficou alguma dúvida sobre os exames do seu pedido — preparo, convênio, forma de pagamento ou qualquer outra coisa.\n\n` +
      `Às vezes uma pergunta não respondida é o que impede a gente de dar o próximo passo. Pode me perguntar à vontade!\n\n` +
      `Também posso verificar se seu convênio cobre algum exame ou ajudar a organizar tudo no mesmo dia. 🗓️\n\n` +
      `O que posso fazer por você?\n\n` +
      `_Total Quality — (12) 3887-3535_`
  },

  // ── FU-5: Diferencial + facilidade de pagamento (dia 21) ──────────
  {
    tag: '[FOLLOWUP-5]',
    texto: (nome) =>
      `${nome}, que tal cuidar da sua saúde ainda esse mês? 🌟\n\n` +
      `Na *Total Quality* você tem condições especiais de pagamento:\n\n` +
      `💚 *PIX* — sem taxa adicional (o mais econômico!)\n` +
      `💳 *Cartão crédito* — até 3x sem juros\n` +
      `🏦 *Débito* — todas as bandeiras\n\n` +
      `Seja qual for o exame — laboratorial, ultrassom, tomografia, cardiologia — você recebe resultado rápido e laudo especializado. 🏆\n\n` +
      `Ainda consigo reservar seu horário esta semana. É só me dizer! 😊\n\n` +
      `_Total Quality — (12) 3887-3535_`
  },

  // ── FU-6: Mensagem final — porta aberta (dia 30) ─────────────────
  {
    tag: '[FOLLOWUP-6]',
    texto: (nome) =>
      `${nome}, esse é nosso último contato automático — e queremos que saiba que as portas da *Total Quality* estão sempre abertas para você! ❤️\n\n` +
      `Quando estiver pronto(a) para cuidar da sua saúde, é só nos chamar aqui no WhatsApp ou ligar:\n\n` +
      `📞 *(12) 3887-3535*\n` +
      `🕗 Segunda a Sexta, 8h às 18h\n` +
      `📍 Caraguatatuba, SP — Litoral Norte\n\n` +
      `Cuide-se muito! 💛\n\n` +
      `_Total Quality Medicina Diagnóstica — 23 anos cuidando de você_`
  }
];

// ── Processar cada paciente ───────────────────────────────────────
const itens = $input.all();

const resultado = itens.map(item => {
  const {
    phone,
    patient_name,
    followup_count,
    stage,
    dias_desde_contato
  } = item.json;

  const idx    = Math.min(parseInt(followup_count) || 0, CADENCIA.length - 1);
  const etapa  = CADENCIA[idx];
  const nome   = (patient_name || 'Prezado(a)').split(' ')[0]; // apenas primeiro nome
  const texto  = etapa.texto(nome);
  const tag    = etapa.tag;
  const numero = idx + 1;

  return {
    json: {
      phone,
      patient_name,
      remoteJid:        `${phone}@s.whatsapp.net`,
      followup_count:   parseInt(followup_count) || 0,
      followup_numero:  numero,
      followup_tag:     tag,
      stage,
      dias_desde_contato,
      mensagem_completa: `${tag}\n${texto}`,
      mensagem_paciente:  texto   // texto limpo para o paciente (sem tag)
    }
  };
});

return resultado;

